PRAGMA foreign_keys = ON;
CREATE TABLE test_cases(id TEXT PRIMARY KEY, category TEXT NOT NULL, tier TEXT NOT NULL, priority TEXT NOT NULL, title TEXT NOT NULL, expected_result TEXT NOT NULL, sort_order INTEGER NOT NULL, active INTEGER NOT NULL DEFAULT 1);
CREATE TABLE sessions(id TEXT PRIMARY KEY, name TEXT NOT NULL, join_code_hash TEXT UNIQUE NOT NULL, created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')), active INTEGER NOT NULL DEFAULT 1 CHECK(active IN (0,1)), mode TEXT NOT NULL CHECK(mode IN ('QUICK','CORE','ALL','CUSTOM')));
CREATE TABLE session_tests(session_id TEXT REFERENCES sessions(id),test_id TEXT REFERENCES test_cases(id),position INTEGER NOT NULL,PRIMARY KEY(session_id,test_id));
CREATE TABLE participants(id TEXT PRIMARY KEY,session_id TEXT NOT NULL REFERENCES sessions(id),first_name TEXT NOT NULL,last_initial TEXT NOT NULL,team TEXT NOT NULL,token_hash TEXT UNIQUE NOT NULL,registration_hash TEXT UNIQUE NOT NULL,created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),last_seen_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),UNIQUE(session_id,id));
CREATE TABLE results(session_id TEXT NOT NULL,participant_id TEXT NOT NULL,test_id TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN ('pass','partial_pass','fail','skipped')),comment TEXT NOT NULL CHECK(length(comment)<=3000 AND (status NOT IN ('fail','partial_pass') OR length(trim(comment))>=2)),version INTEGER NOT NULL CHECK(version>0),last_mutation_id TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),PRIMARY KEY(session_id,participant_id,test_id),FOREIGN KEY(session_id,participant_id) REFERENCES participants(session_id,id),FOREIGN KEY(session_id,test_id) REFERENCES session_tests(session_id,test_id));
CREATE TABLE mutation_receipts(participant_id TEXT NOT NULL REFERENCES participants(id),mutation_id TEXT NOT NULL,payload TEXT NOT NULL,result TEXT NOT NULL,PRIMARY KEY(participant_id,mutation_id));
CREATE TRIGGER result_receipt_insert AFTER INSERT ON results BEGIN INSERT INTO mutation_receipts VALUES(NEW.participant_id,NEW.last_mutation_id,json_object('testId',NEW.test_id,'status',NEW.status,'comment',NEW.comment,'expectedVersion',0),json_object('test_id',NEW.test_id,'status',NEW.status,'comment',NEW.comment,'version',NEW.version,'updated_at',NEW.updated_at)); END;
CREATE TRIGGER result_receipt_update AFTER UPDATE ON results BEGIN INSERT INTO mutation_receipts VALUES(NEW.participant_id,NEW.last_mutation_id,json_object('testId',NEW.test_id,'status',NEW.status,'comment',NEW.comment,'expectedVersion',OLD.version),json_object('test_id',NEW.test_id,'status',NEW.status,'comment',NEW.comment,'version',NEW.version,'updated_at',NEW.updated_at)); END;
CREATE TABLE rate_limits(key TEXT PRIMARY KEY,window INTEGER NOT NULL,count INTEGER NOT NULL);
CREATE INDEX results_status ON results(session_id,status,test_id);
CREATE INDEX participants_session ON participants(session_id,team);
CREATE INDEX session_position ON session_tests(session_id,position);
CREATE INDEX tests_category ON test_cases(category,priority);
